## 3. Result-Generation Logic (form data → recommendation)

Source: `client/src/lib/rotatorCuffLogic.ts`

```typescript
export type TearSize = "small" | "medium" | "large" | "massive";

export type RotatorCuffInput = {
  age: string; affectedSide: string; tearSize: string; symptomDurationMonths: string;
  painScore: string; symptoms: string[]; conservativeTherapyMonths: string;
  conservativeTherapies: string[]; tearCharacteristics: string[];
  acuteTear: boolean; dominantArm: boolean; highDemandActivity: boolean;
  activeInfection: boolean; severeGlenohumeralArthritis: boolean;
};

export type COR = "I" | "IIa" | "IIb" | "III";

export function getCORLabel(cor: COR): string {
  return { I: "Class I — Recommended", IIa: "Class IIa — Reasonable", IIb: "Class IIb — May Be Considered", III: "Class III — Not Recommended" }[cor];
}
export function getCORColor(cor: COR): string {
  return { I: "border-green-500 text-green-700", IIa: "border-blue-500 text-blue-700", IIb: "border-yellow-500 text-yellow-700", III: "border-red-500 text-red-700" }[cor];
}

export function assessRotatorCuff(input: RotatorCuffInput) {
  const conservMonths = parseFloat(input.conservativeTherapyMonths) || 0;
  const painScore = parseFloat(input.painScore) || 0;

  const contraindications: string[] = [];
  if (input.activeInfection) contraindications.push("Active shoulder infection — absolute contraindication");
  if (input.severeGlenohumeralArthritis) contraindications.push("Severe glenohumeral arthritis — consider shoulder arthroplasty instead");

  if (contraindications.length > 0) {
    return { recommendation: "Arthroscopic Repair Contraindicated", cor: "III" as COR, loe: "C", urgency: "Contraindicated", rationale: ["Contraindications identified."], contraindications, optimizationSteps: [] };
  }

  const rationale: string[] = [];
  const optimizationSteps: string[] = [];
  let cor: COR = "IIb";
  let urgency = "Elective";

  const isFullThickness = input.tearCharacteristics.includes("full-thickness");
  const isLargeOrMassive = input.tearSize === "large" || input.tearSize === "massive";
  const hasRetraction = input.tearCharacteristics.includes("retraction");
  const hasAtrophy = input.tearCharacteristics.includes("muscle-atrophy");

  if (input.acuteTear && isFullThickness) {
    cor = "I"; urgency = "Urgent";
    rationale.push("Acute full-thickness rotator cuff tear — early repair (within 6 weeks) strongly recommended");
    rationale.push("Delayed repair risks irreversible muscle atrophy and retraction");
  } else if (isFullThickness && conservMonths >= 3 && painScore >= 6) {
    cor = "I"; urgency = "Appropriate";
    rationale.push("Full-thickness tear with persistent pain and functional limitation after conservative therapy");
    rationale.push("Surgical repair recommended per AAOS guidelines");
  } else if (isLargeOrMassive) {
    cor = "IIa"; urgency = "Appropriate";
    rationale.push("Large or massive tear — surgical repair or debridement recommended");
    if (hasRetraction || hasAtrophy) optimizationSteps.push("Significant retraction/atrophy noted — repair may be technically challenging; consider tendon transfer");
  } else if (conservMonths < 3 && !input.acuteTear) {
    cor = "IIb"; urgency = "Continue Conservative Therapy";
    rationale.push("Conservative therapy trial insufficient — continue for ≥3 months");
    optimizationSteps.push("Continue PT focusing on rotator cuff strengthening and scapular stabilization");
    optimizationSteps.push("Consider subacromial corticosteroid injection");
  } else {
    cor = "IIa"; urgency = "Reasonable";
    rationale.push("Rotator cuff repair is reasonable given tear characteristics and clinical presentation");
  }

  if (input.dominantArm) rationale.push("Dominant arm affected — functional impact supports surgical intervention");
  if (input.highDemandActivity) rationale.push("High-demand overhead activity — repair supports return to activity");

  return { recommendation: cor === "I" ? "Rotator Cuff Repair Recommended" : cor === "IIa" ? "Repair Reasonable" : "Continue Conservative Therapy", cor, loe: isFullThickness ? "A" : "B", urgency, rationale, contraindications, optimizationSteps };
}
```


